"""Plot an order-locked response generated by a synchronous harmonic load."""

from matplotlib import pyplot as plt
import numpy as np

from spinniped import (
    BearingElement,
    BearingProperty,
    DiskElement,
    DiskProperty,
    Grid,
    ModelBuilder,
    ModelDefinition,
    Solver,
    SynchronousLoad,
)


# A synchronous load inherits the component-vector convention of HarmonicLoad.
# harmonic_order=2.0 locks its excitation to twice the absolute rotor speed.
definition = ModelDefinition(
    grids=[Grid(1)],
    properties=[
        BearingProperty(id=1, kxx=1.20e6, cxx=500.0),
        DiskProperty(
            id=2,
            mass=10.0,
            diametral_inertia=0.05,
            polar_inertia=0.10,
        ),
    ],
    elements=[
        BearingElement(id=1, grid=1, property=1),
        DiskElement(id=2, grid=1, property=2),
    ],
    loads=[
        SynchronousLoad(
            id=1,
            grid=1,
            harmonic_order=2.0,
            force=(100.0, 0.0, 0.0),
        )
    ],
)

model = ModelBuilder().build(definition)
solver = Solver(model)

# frequency_response accepts one scalar rotor speed per call. For a
# SynchronousLoad, frequencies must be omitted because the solver derives the
# single excitation frequency from harmonic_order * abs(speed).
speeds_rpm = np.linspace(0.0, 6_000.0, 121)
rpm_to_rad_per_second = 2.0 * np.pi / 60.0
speeds = speeds_rpm * rpm_to_rad_per_second
response_amplitudes = []
forcing_frequencies = []

for speed in speeds:
    result = solver.solve(
        "frequency_response",
        fixed_dofs=[1, 2, 3, 4, 5],
        speed=float(speed),
        load_ids=[1],
    )
    response_amplitudes.append(abs(result["response"][0, 0, 0]))
    forcing_frequencies.append(result["frequencies"][0])

figure, response_axes = plt.subplots()
response_line = response_axes.plot(
    speeds_rpm,
    response_amplitudes,
    label="x response",
)[0]
response_axes.set_xlabel("Rotor speed [rpm]")
response_axes.set_ylabel("x amplitude [m]")
response_axes.set_title("2x synchronous harmonic response")
response_axes.grid(True, alpha=0.3)

frequency_axes = response_axes.twinx()
frequency_line = frequency_axes.plot(
    speeds_rpm,
    forcing_frequencies,
    "--",
    color="tab:orange",
    label="derived 2x frequency",
)[0]
frequency_axes.set_ylabel("Forcing frequency [Hz]")
response_axes.legend(handles=[response_line, frequency_line])

figure.tight_layout()
plt.show()
